<template>
  <section class="enhanced-page">
    <header class="page-head">
      <div><p class="eyebrow">TASKS · ENHANCED</p><h1>{{ title }}</h1><p>{{ subtitle }}</p></div>
    </header>

    <p v-if="error" class="notice error">{{ error }}</p><p v-if="message" class="notice success">{{ message }}</p>

    <template v-if="mode === 'board' || mode === 'quadrant'">
      <div v-if="mode === 'board'" class="toolbar"><label>分列方式<select v-model="dimension" @change="loadBoard"><option value="list">清单</option><option value="status">状态</option><option value="priority">优先级</option><option value="tag">标签</option></select></label><span>拖动卡片可修改对应字段；移动端请使用卡片菜单。</span></div>
      <div class="board" :class="{ quadrant: mode === 'quadrant' }">
        <section v-for="column in board.columns" :key="column.key" class="board-column" @dragover.prevent @drop="drop(column)">
          <header class="board-column-head"><h2>{{ column.label }}</h2><div><b>{{ column.tasks.length }}</b><button v-if="mode === 'board' && canAddToColumn(column)" type="button" :aria-label="`在${column.label}添加任务`" :title="`在${column.label}添加任务`" @click="openBoardAdd(column)"><Plus :size="15" /></button></div></header>
          <div class="cards">
            <article v-for="task in column.tasks" :key="task.publicId" class="task-card" draggable="true" @dragstart="dragged = task">
              <strong>{{ task.title }}</strong><small>{{ dueLabel(task.dueAt) }}</small>
              <div><span :class="`priority ${task.priority.toLowerCase()}`">{{ priorityLabel(task.priority) }}</span><span v-if="task.totalSubtasks">{{ task.completedSubtasks }}/{{ task.totalSubtasks }}</span></div>
              <select aria-label="移动任务" @change="moveByMenu(task, $event.target.value); $event.target.value=''">
                <option value="">移动到…</option><option v-for="target in board.columns.filter(v => v.key !== column.key)" :key="target.key" :value="target.key">{{ target.label }}</option>
              </select>
            </article><p v-if="!column.tasks.length" class="empty">暂无任务</p>
          </div>
        </section>
      </div>
    </template>

    <template v-else-if="mode === 'search'">
      <section class="panel search-panel"><h2>全局搜索</h2><form class="search-row" @submit.prevent="runSearch"><input v-model.trim="query" maxlength="200" placeholder="搜索任务、清单或标签" autofocus><button>搜索</button></form>
        <div class="search-filters" aria-label="搜索条件"><label>范围<select v-model="searchScope"><option value="ALL">全部</option><option value="TASKS">任务</option><option value="LISTS">清单</option><option value="TAGS">标签</option></select></label><label>状态<select v-model="searchStatus"><option value="ALL">全部状态</option><option value="OPEN">待完成</option><option value="COMPLETED">已完成</option></select></label><label>优先级<select v-model="searchPriority"><option value="ALL">全部优先级</option><option value="HIGH">高</option><option value="MEDIUM">中</option><option value="LOW">低</option><option value="NONE">无</option></select></label><label>日期<select v-model="searchDue"><option value="ALL">全部日期</option><option value="TODAY">今天</option><option value="OVERDUE">已逾期</option><option value="NONE">无日期</option></select></label></div>
        <div v-if="recentSearches.length" class="recent-searches"><span>最近搜索</span><button v-for="item in recentSearches" :key="item" type="button" @click="query=item;runSearch()">{{ item }}</button></div>
        <div v-if="searchResult" class="search-results"><ResultGroup v-if="searchScope === 'ALL' || searchScope === 'TASKS'" title="任务" :items="filteredSearchTasks" :query="query"/><ResultGroup v-if="searchScope === 'ALL' || searchScope === 'LISTS'" title="清单" :items="searchResult.lists" :query="query"/><ResultGroup v-if="searchScope === 'ALL' || searchScope === 'TAGS'" title="标签" :items="searchResult.tags" :query="query"/></div>
      </section>
      <section class="panel"><h2>快速添加</h2><form class="search-row" @submit.prevent="parseQuick"><input v-model.trim="quickText" maxlength="500" placeholder="例如：明天 提交周报 !!! #工作 @收件箱"><button>解析</button></form>
        <div v-if="draft" class="draft"><label>标题<input v-model="draft.title"></label><label>优先级<select v-model="draft.priority"><option v-for="p in priorities" :key="p" :value="p">{{ priorityLabel(p) }}</option></select></label><label>到期时间<input v-model="draftDue" type="datetime-local"></label><button @click="createDraft">确认新增</button></div>
      </section>
      <section class="panel"><div class="panel-title"><h2>智能清单</h2><button @click="editFilter()">新建</button></div><div class="filter-grid"><article v-for="filter in filters" :key="filter.publicId"><RouterLink :to="`/tasks/filter/${filter.publicId}`"><b>{{ filter.name }}</b><small>{{ filterSummary(filter) }}</small></RouterLink><button @click="editFilter(filter)">编辑</button><button class="danger" @click="removeFilter(filter)">删除</button></article></div></section>
    </template>

    <template v-else-if="mode === 'filter'">
      <section class="panel"><div class="panel-title"><h2>{{ activeFilter?.name || '智能清单' }}</h2><button @click="editFilter(activeFilter)">编辑条件</button></div><p>{{ activeFilter ? filterSummary(activeFilter) : '' }}</p><div class="task-list"><article v-for="task in filteredTasks" :key="task.publicId"><button class="check" @click="toggleTask(task)">{{ task.status === 'COMPLETED' ? '✓' : '○' }}</button><div><b>{{ task.title }}</b><small>{{ dueLabel(task.dueAt) }} · {{ priorityLabel(task.priority) }}</small></div></article><p v-if="!filteredTasks.length" class="empty">当前没有匹配任务</p></div></section>
    </template>

    <template v-else-if="mode === 'stats'">
      <div class="toolbar"><label>开始<input v-model="statsRange.from" type="date"></label><label>结束<input v-model="statsRange.to" type="date"></label><button @click="loadStats">刷新</button></div>
      <div v-if="stats" class="metric-grid"><article><span>新建任务</span><b>{{ stats.created }}</b></article><article><span>完成任务</span><b>{{ stats.completed }}</b></article><article><span>完成率</span><b>{{ stats.completionRate.toFixed(1) }}%</b></article><article><span>逾期完成</span><b>{{ stats.overdueCompleted }}</b></article><article><span>平均完成时延</span><b>{{ stats.averageCompletionHours.toFixed(1) }}h</b></article><article><span>专注时长</span><b>{{ stats.focusMinutes }}m</b></article></div>
      <div v-if="stats" class="distribution-grid"><Distribution title="优先级分布" :values="stats.byPriority"/><Distribution title="清单分布" :values="stats.byList"/><Distribution title="标签分布" :values="stats.byTag"/></div>
      <p class="basis-note">专注时长是主动专注口径，不写入工时记录，也不参与工资、加班或实际时薪计算。</p>
    </template>

    <Dialog v-model:open="filterOpen" title="智能清单条件">
      <form class="filter-form" @submit.prevent="saveFilter"><label>名称<input v-model.trim="filterForm.name" required maxlength="120"></label><label>状态<select v-model="filterForm.status"><option value="OPEN">待完成</option><option value="COMPLETED">已完成</option><option value="ALL">全部</option></select></label><label>到期范围<select v-model="filterForm.dueRange"><option value="ANY">不限</option><option value="TODAY">今天</option><option value="TOMORROW">明天</option><option value="NEXT7">最近 7 天</option><option value="OVERDUE">已逾期</option><option value="NONE">无日期</option></select></label><label>关键词<input v-model.trim="filterForm.keyword" maxlength="200"></label><fieldset><legend>优先级</legend><label v-for="p in priorities" :key="p"><input v-model="filterForm.priorities" type="checkbox" :value="p">{{ priorityLabel(p) }}</label></fieldset><fieldset><legend>清单</legend><label v-for="list in store.lists" :key="list.publicId"><input v-model="filterForm.listIds" type="checkbox" :value="list.publicId">{{ list.name }}</label></fieldset><fieldset><legend>标签</legend><label v-for="tag in store.tags" :key="tag.publicId"><input v-model="filterForm.tagIds" type="checkbox" :value="tag.publicId">{{ tag.name }}</label></fieldset><label class="inline"><input v-model="filterForm.matchAllTags" type="checkbox">匹配全部所选标签</label><label class="inline"><input v-model="filterForm.includeSubtasks" type="checkbox">包含子任务</label><label class="inline"><input v-model="filterForm.pinned" type="checkbox">置顶</label><footer><button type="button" @click="filterOpen=false">取消</button><button>保存</button></footer></form>
    </Dialog>
    <Dialog v-model:open="boardAddOpen" :title="`添加任务 · ${boardAddTarget?.label || ''}`">
      <form class="board-add-form" @submit.prevent="saveBoardTask">
        <label>任务名称<input v-model.trim="boardAddTitle" autofocus maxlength="500" required aria-label="看板任务名称" /></label>
        <label>日期<input v-model="boardAddDue" type="datetime-local" aria-label="看板任务日期" /></label>
        <label>优先级<select v-model="boardAddPriority" aria-label="看板任务优先级"><option value="NONE">无</option><option value="LOW">低</option><option value="MEDIUM">中</option><option value="HIGH">高</option></select></label>
        <footer><button type="button" @click="boardAddOpen = false">取消</button><button type="submit" :disabled="!boardAddTitle || store.saving">添加</button></footer>
      </form>
    </Dialog>
  </section>
</template>

<script setup>
import { computed, defineComponent, h, onMounted, reactive, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { Plus } from 'lucide-vue-next'
import Dialog from '../components/ui/Dialog.vue'
import { useAppStore } from '../stores/app.js'
import { useTasksStore } from '../stores/tasks.js'
import { apiCreateTaskFilter, apiDeleteTaskFilter, apiGetTaskBoard, apiGetTaskQuadrant, apiGetTaskStats, apiListTaskFilters, apiListTaskFilterTasks, apiParseTaskQuickAdd, apiSearchTasks, apiUpdateTaskFilter } from '../../packages/api-client/src/index.js'

const route=useRoute(),appStore=useAppStore(),store=useTasksStore(),error=ref(''),message=ref(''),dimension=ref('list'),board=reactive({columns:[]}),dragged=ref(null),query=ref(''),searchResult=ref(null),recentSearches=ref([]),quickText=ref(''),draft=ref(null),draftDue=ref(''),filters=ref([]),filteredTasks=ref([]),stats=ref(null),filterOpen=ref(false),editingFilter=ref(null)
const boardAddOpen=ref(false),boardAddTarget=ref(null),boardAddTitle=ref(''),boardAddDue=ref(''),boardAddPriority=ref('NONE')
const priorities=['NONE','LOW','MEDIUM','HIGH'];const now=new Date(),monthStart=new Date(now.getFullYear(),now.getMonth(),1)
const searchScope=ref('ALL'),searchStatus=ref('ALL'),searchPriority=ref('ALL'),searchDue=ref('ALL')
const filteredSearchTasks=computed(()=>{const rows=searchResult.value?.tasks||[];const today=localDate(new Date());return rows.filter(task=>(searchStatus.value==='ALL'||(searchStatus.value==='COMPLETED' ? task.status==='COMPLETED' : task.status!=='COMPLETED'))&&(searchPriority.value==='ALL'||task.priority===searchPriority.value)&&(searchDue.value==='ALL'||(searchDue.value==='NONE'?!task.dueAt:searchDue.value==='OVERDUE'?task.dueAt&&task.dueAt.slice(0,10)<today:task.dueAt?.slice(0,10)===today)))})
const statsRange=reactive({from:localDate(monthStart),to:localDate(now)});const filterForm=reactive({name:'',listIds:[],tagIds:[],priorities:[],status:'OPEN',dueRange:'ANY',keyword:'',includeSubtasks:true,matchAllTags:false,sortOrder:0,pinned:false})
const mode=computed(()=>route.name==='tasks-quadrant'?'quadrant':route.name==='tasks-search'?'search':route.name==='tasks-stats'?'stats':route.name==='tasks-filter'?'filter':'board')
const title=computed(()=>({board:'任务看板',quadrant:'四象限',search:'搜索与智能清单',filter:'智能清单',stats:'任务统计与回顾'}[mode.value]));const subtitle=computed(()=>({board:'按不同维度组织任务并快速移动',quadrant:'把重要与紧急分开，决定下一步',search:'从任务、清单和标签中快速定位',filter:'条件变化后实时重算结果',stats:'从完成、逾期和专注角度回顾'}[mode.value]));const activeFilter=computed(()=>filters.value.find(v=>v.publicId===route.params.publicId))
const ResultGroup=defineComponent({props:['title','items','query'],setup(p){return()=>h('section',{class:'result-group'},[h('h3',`${p.title} ${p.items?.length||0}`),...(p.items||[]).map(item=>h('article',[h('b',highlight(item.title||item.name,p.query)),item.description?h('small',item.description):null]))])}})
const Distribution=defineComponent({props:['title','values'],setup(p){return()=>h('section',{class:'panel distribution'},[h('h2',p.title),...Object.entries(p.values||{}).map(([k,v])=>h('div',[h('span',k),h('i',{style:{width:`${Math.min(100,Number(v)*8)}%`}}),h('b',String(v))]))])}})
function detail(e){return e?.response?.data?.detail||e?.message||'操作失败'}function localDate(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}function dueLabel(v){return v?new Date(v).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'}):'无日期'}function priorityLabel(v){return({NONE:'无',LOW:'低',MEDIUM:'中',HIGH:'高'}[v]||v)}function highlight(v,q){const value=String(v||''),needle=String(q||'').trim();if(!needle)return value;const index=value.toLowerCase().indexOf(needle.toLowerCase());return index<0?value:[value.slice(0,index),h('mark',value.slice(index,index+needle.length)),value.slice(index+needle.length)]}function setNotice(v){message.value=v;setTimeout(()=>{if(message.value===v)message.value=''},3000)}
function recentSearchKey(){return `task_recent_searches:${appStore.accountScope||appStore.authUser?.id||'anonymous'}`}function loadRecentSearches(){try{recentSearches.value=JSON.parse(localStorage.getItem(recentSearchKey())||'[]').filter(v=>typeof v==='string').slice(0,10)}catch{recentSearches.value=[]}}
async function loadBoard(){try{error.value='';const data=mode.value==='quadrant'?await apiGetTaskQuadrant():await apiGetTaskBoard(dimension.value);board.columns=data?.columns||[]}catch(e){error.value=detail(e)}}
function canAddToColumn(column){return dimension.value!=='status'||column.key==='OPEN'}
function openBoardAdd(column){boardAddTarget.value=column;boardAddTitle.value='';boardAddDue.value='';boardAddPriority.value=dimension.value==='priority'?column.key:'NONE';boardAddOpen.value=true}
async function saveBoardTask(){const column=boardAddTarget.value;if(!column||!boardAddTitle.value)return;const payload={title:boardAddTitle.value,description:'',listId:dimension.value==='list'?column.key:(store.inbox?.publicId||''),priority:dimension.value==='priority'?column.key:boardAddPriority.value,dueAt:boardAddDue.value?new Date(boardAddDue.value).toISOString():'',tagIds:dimension.value==='tag'&&column.key!=='NONE'?[column.key]:[]};try{await store.create(payload);boardAddOpen.value=false;await loadBoard();setNotice('任务已添加')}catch(e){error.value=detail(e)}}
async function moveTask(task,key){let payload={};if(mode.value==='quadrant'){const important=key.startsWith('IMPORTANT_'),urgent=key.endsWith('_URGENT');payload.priority=important?(task.priority==='HIGH'?'HIGH':'MEDIUM'):'LOW';if(urgent&&!task.dueAt)payload.dueAt=new Date(new Date().setHours(23,59,0,0)).toISOString();if(!urgent&&task.dueAt&&new Date(task.dueAt)<=new Date())payload.dueAt=new Date(Date.now()+7*86400000).toISOString()}else if(dimension.value==='list')payload.listId=key;else if(dimension.value==='priority')payload.priority=key;else if(dimension.value==='status'){await(key==='COMPLETED'?store.complete(task):store.reopen(task));await loadBoard();return}else if(dimension.value==='tag')payload.tagIds=key==='NONE'?[]:[...new Set([...(task.tagIds||[]),key])];await store.update(task,payload);await loadBoard()}
async function drop(column){if(!dragged.value)return;try{await moveTask(dragged.value,column.key)}catch(e){error.value=detail(e)}finally{dragged.value=null}}async function moveByMenu(task,key){if(key)try{await moveTask(task,key)}catch(e){error.value=detail(e)}}
async function runSearch(){if(!query.value)return;try{searchResult.value=await apiSearchTasks(query.value);recentSearches.value=[query.value,...recentSearches.value.filter(v=>v!==query.value)].slice(0,10);localStorage.setItem(recentSearchKey(),JSON.stringify(recentSearches.value))}catch(e){error.value=detail(e)}}
async function parseQuick(){try{draft.value=await apiParseTaskQuickAdd(quickText.value);draftDue.value=draft.value.dueAt?new Date(new Date(draft.value.dueAt).getTime()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16):''}catch(e){error.value=detail(e)}}async function createDraft(){try{const list=store.lists.find(v=>v.name===draft.value.listName)||store.inbox;const tags=store.tags.filter(v=>draft.value.tagNames?.includes(v.name)).map(v=>v.publicId);await store.create({title:draft.value.title,description:'',priority:draft.value.priority,dueAt:draftDue.value?new Date(draftDue.value).toISOString():'',listId:list?.publicId,tagIds:tags,rrule:draft.value.rrule});quickText.value='';draft.value=null;setNotice('任务已新增')}catch(e){error.value=detail(e)}}
async function loadFilters(){try{filters.value=await apiListTaskFilters()}catch(e){error.value=detail(e)}}function filterSummary(f){return[({OPEN:'待完成',COMPLETED:'已完成',ALL:'全部'}[f.status]),f.dueRange!=='ANY'?f.dueRange:'',f.keyword?`含“${f.keyword}”`:'',f.priorities?.map(priorityLabel).join('/')].filter(Boolean).join(' · ')}function editFilter(f=null){editingFilter.value=f;Object.assign(filterForm,f?JSON.parse(JSON.stringify(f)):{name:'',listIds:[],tagIds:[],priorities:[],status:'OPEN',dueRange:'ANY',keyword:'',includeSubtasks:true,matchAllTags:false,sortOrder:filters.value.length,pinned:false});filterOpen.value=true}async function saveFilter(){try{if(editingFilter.value)await apiUpdateTaskFilter(editingFilter.value.publicId,filterForm,editingFilter.value.revision);else await apiCreateTaskFilter(filterForm);filterOpen.value=false;await loadFilters();if(mode.value==='filter')await loadFiltered();setNotice('智能清单已保存')}catch(e){error.value=detail(e)}}async function removeFilter(f){if(!confirm(`删除智能清单“${f.name}”？任务不会被删除。`))return;try{await apiDeleteTaskFilter(f.publicId,f.revision);await loadFilters()}catch(e){error.value=detail(e)}}async function loadFiltered(){if(!route.params.publicId)return;try{filteredTasks.value=(await apiListTaskFilterTasks(route.params.publicId,{size:200}))?.items||[]}catch(e){error.value=detail(e)}}async function toggleTask(task){await(task.status==='COMPLETED'?store.reopen(task):store.complete(task));await loadFiltered()}
async function loadStats(){try{stats.value=await apiGetTaskStats(statsRange)}catch(e){error.value=detail(e)}}
async function load(){error.value='';await store.init();await loadFilters();if(['board','quadrant'].includes(mode.value))await loadBoard();if(mode.value==='search')loadRecentSearches();if(mode.value==='filter')await loadFiltered();if(mode.value==='stats')await loadStats()}
watch(()=>route.fullPath,load);onMounted(load)
</script>

<style scoped>
.enhanced-page{display:grid;gap:18px;max-width:1440px;margin:0 auto;padding:8px 0 48px}.page-head{display:flex;justify-content:space-between;gap:20px;align-items:flex-end}.page-head h1{margin:3px 0;font-size:clamp(24px,3vw,36px)}.page-head p{margin:0;color:var(--muted)}.eyebrow{font-size:12px!important;font-weight:800;letter-spacing:.12em;color:var(--primary)!important}.toolbar button,.panel button,.search-row button{border:1px solid var(--border);background:var(--surface);color:var(--text);padding:9px 13px;border-radius:10px;text-decoration:none;font-weight:650}.toolbar{display:flex;gap:14px;align-items:center;flex-wrap:wrap;padding:12px 14px;border:1px solid var(--border);background:var(--surface);border-radius:14px}.toolbar label,.filter-form label,.draft label{display:grid;gap:5px}.toolbar span{color:var(--muted);font-size:13px}.toolbar select,.toolbar input,input,select{min-height:38px;border:1px solid var(--border);border-radius:9px;background:var(--surface);color:var(--text);padding:7px 10px}.board{display:grid;grid-auto-flow:column;grid-auto-columns:minmax(280px,1fr);gap:14px;overflow-x:auto;padding-bottom:8px}.board.quadrant{grid-template-columns:repeat(2,minmax(0,1fr));grid-auto-flow:row}.board-column{background:color-mix(in srgb,var(--surface) 88%,var(--primary) 12%);border:1px solid var(--border);border-radius:16px;min-height:420px;padding:12px}.board-column>header{display:flex;justify-content:space-between;align-items:center;padding:3px 4px 12px}.board-column h2{font-size:15px;margin:0}.board-column header b{background:var(--surface);border-radius:20px;padding:3px 8px}.cards{display:grid;gap:9px}.task-card{display:grid;gap:8px;background:var(--surface);border:1px solid var(--border);border-radius:12px;padding:12px;box-shadow:0 5px 16px rgba(15,23,42,.05)}.task-card small,.task-card div{color:var(--muted);font-size:12px}.task-card div{display:flex;justify-content:space-between}.task-card select{display:none}.priority.high{color:#dc2626}.priority.medium{c